import java.util.*;
public class Main {static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}long next()throws Exception{int c;do{c=read();}while(c<=32&&c!=-1);long x=0;while(c>32){x=x*10+c-48;c=read();}return x;}}
 static TreeMap<Long,Long> intervals;static long covered;
 static void add(long a,long b){long l=b-a+1,r=a+b-1;if(l>r)return;Map.Entry<Long,Long> e=intervals.floorEntry(l);if(e!=null&&e.getValue()>=l-1){l=e.getKey();r=Math.max(r,e.getValue());covered-=e.getValue()-e.getKey()+1;intervals.remove(e.getKey());}while((e=intervals.ceilingEntry(l))!=null&&e.getKey()<=r+1){r=Math.max(r,e.getValue());covered-=e.getValue()-e.getKey()+1;intervals.remove(e.getKey());}intervals.put(l,r);covered+=r-l+1;}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int t=(int)in.next();StringBuilder out=new StringBuilder();while(t-->0){int n=(int)in.next();TreeSet<Long> values=new TreeSet<>();intervals=new TreeMap<>();covered=0;for(int i=0;i<n;i++){long x=in.next();Long a=values.lower(x),b=values.higher(x);if(a!=null)add(a,x);if(b!=null)add(x,b);values.add(x);if(i>0){if(i>1)out.append(' ');out.append(covered);}}out.append('\n');}System.out.print(out);}}
